<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><div class="page"><h1>Customers</h1><form class="admin-form" method="get" action="<?= site_url('admin/customers') ?>"><label>Search customers<input name="q" type="search" value="<?= esc($query) ?>"></label><button type="submit">Search</button></form><?php if (! $customers): ?><p>No customers yet.</p><?php endif ?><?php foreach ($customers as $customer): ?><article class="admin-item"><h2><?= esc($customer['name']) ?></h2><p><?= esc($customer['email']) ?> · <?= $customer['is_active'] ? 'Active' : 'Inactive' ?></p></article><?php endforeach ?><div class="pagination"><?= $pager->links() ?></div></div><?= $this->endSection() ?>
